 private abstract class Review<T : Entity>(id: String? = null) : Entity(id) {
     val rating: Int? = null
     val content: T? = null
 }

 private class Review1(id: String? = null) : Review<Place1>(id)

 private class Review2(id: String? = null) : Review<Place2>(id)

